  "footer.source": { en: "Long-run GDP data: Bolt, J. &amp; van Zanden, J. L. (2024), \"Maddison style estimates of the evolution of the world economy: A new 2023 update,\" <em>Journal of Economic Surveys</em>. <a href=\"https://www.rug.nl/ggdc/historicaldevelopment/maddison/releases/maddison-project-database-2023\">Maddison Project Database 2023</a>.", es: "Datos de PIB de largo plazo: Bolt, J. y van Zanden, J. L. (2024), \"Maddison style estimates of the evolution of the world economy: A new 2023 update,\" <em>Journal of Economic Surveys</em>. <a href=\"https://www.rug.nl/ggdc/historicaldevelopment/maddison/releases/maddison-project-database-2023\">Maddison Project Database 2023</a>.", ja: "長期GDPデータ：Bolt, J. &amp; van Zanden, J. L. (2024), \"Maddison style estimates of the evolution of the world economy: A new 2023 update,\" <em>Journal of Economic Surveys</em>. <a href=\"https://www.rug.nl/ggdc/historicaldevelopment/maddison/releases/maddison-project-database-2023\">Maddison Project Database 2023</a>。" },
  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 2: Univariate Data Summary · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 2: Resumen de datos univariados · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", ja: "<a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> の一部 · 第2章：一変量データの要約 · Carlos Mendez 著 · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
  "header.badge": { en: "Chapter 2 of 18 · Interactive Dashboard", es: "Capítulo 2 de 18 · Tablero interactivo", ja: "第2章 / 全18章 · インタラクティブ・ダッシュボード" },
  "header.subtitle": { en: "Slide, toggle, and compare to build intuition for summary statistics, histograms, box plots, transformations, and time-series smoothing — using the same datasets and examples as the chapter.", es: "Desliza, alterna y compara para construir intuición sobre estadísticas descriptivas, histogramas, diagramas de caja, transformaciones y suavizado de series temporales — usando los mismos datos y ejemplos del capítulo.", ja: "スライド、切り替え、比較を通じて、要約統計量、ヒストグラム、箱ひげ図、変数変換、時系列平滑化への直感を養いましょう — 章と同じデータセットと例を使用します。" },
